import re

def parse_duration(text):
    if not isinstance(text, str):
        return None
    text = text.strip()
    if not text:
        return None

    # pure digits -> seconds
    if text.isdigit():
        return int(text)

    # h/m/s components in order, each at most once
    m = re.fullmatch(r'(?:(\d+)h)?(?:(\d+)m)?(?:(\d+)s)?', text)
    if not m:
        return None

    h, mi, s = m.groups()
    if not any([h, mi, s]):          # nothing parsed
        return None

    total = 0
    if h:
        total += int(h) * 3600
    if mi:
        total += int(mi) * 60
    if s:
        total += int(s)
    return total
